import { defaultContainers, sampleCargo, defaultSettings, presetSettings } from './defaults.js'
import { boxVolumeM3, optimizePacking } from './packing.js'

const STORAGE_KEY='container-fit-project-v1'
const $=(sel,root=document)=>root.querySelector(sel)
const $$=(sel,root=document)=>[...root.querySelectorAll(sel)]
const esc=(s='')=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':'&quot;',"'":'&#39;'}[c]))
const clone=x=>JSON.parse(JSON.stringify(x))
const fmt=n=>Number(n||0).toLocaleString('ko-KR',{maximumFractionDigits:1})
const pct=v=>`${Math.max(0,v*100).toFixed(1)}%`

const icons={
 menu:'<path d="M4 7h16M4 12h16M4 17h16"/>', close:'<path d="m6 6 12 12M18 6 6 18"/>', calc:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 7h8M8 11h2m4 0h2M8 15h2m4 0h2M8 19h8"/>', container:'<path d="M3 6.5 12 3l9 3.5v11L12 21l-9-3.5v-11Z"/><path d="M12 3v18M3 6.5l9 3.5 9-3.5M7 8v11M17 8v11"/>', box:'<path d="m21 8-9-5-9 5 9 5 9-5Z"/><path d="m3 8 9 5v8l-9-5V8Zm18 0-9 5v8l9-5V8Z"/>', settings:'<path d="M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7Z"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.83 2.83-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.03 1.56V21h-4v-.08A1.7 1.7 0 0 0 8.97 19.4a1.7 1.7 0 0 0-1.88.34l-.06.06-2.83-2.83.06-.06A1.7 1.7 0 0 0 4.6 15a1.7 1.7 0 0 0-1.56-1.03H3v-4h.08A1.7 1.7 0 0 0 4.6 8.94a1.7 1.7 0 0 0-.34-1.88L4.2 7l2.83-2.83.06.06A1.7 1.7 0 0 0 8.97 4.6 1.7 1.7 0 0 0 10 3.05V3h4v.08a1.7 1.7 0 0 0 1.03 1.56 1.7 1.7 0 0 0 1.88-.34l.06-.06L19.8 7l-.06.06a1.7 1.7 0 0 0-.34 1.88 1.7 1.7 0 0 0 1.56 1.03H21v4h-.08A1.7 1.7 0 0 0 19.4 15Z"/>', layers:'<path d="m12 2 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 17l9 5 9-5"/>', upload:'<path d="M12 3v12m0-12-4 4m4-4 4 4"/><path d="M5 13v6h14v-6"/>', download:'<path d="M12 3v12m0 0-4-4m4 4 4-4"/><path d="M5 19h14"/>', plus:'<path d="M12 5v14M5 12h14"/>', edit:'<path d="m4 20 4.5-1 10-10-3.5-3.5-10 10L4 20Z"/><path d="m13.5 6.5 3.5 3.5"/>', trash:'<path d="M4 7h16M9 7V4h6v3m3 0-1 14H7L6 7m4 4v6m4-6v6"/>', save:'<path d="M5 3h12l2 2v16H5V3Z"/><path d="M8 3v6h8V3M8 21v-8h8v8"/>', reset:'<path d="M4 11a8 8 0 1 1 2 5.5M4 11V6m0 5h5"/>', info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>', check:'<path d="m5 12 4 4L19 6"/>', chevron:'<path d="m9 18 6-6-6-6"/>', up:'<path d="m18 15-6-6-6 6"/>', down:'<path d="m6 9 6 6 6-6"/>', spark:'<path d="m12 3 1.6 4.4L18 9l-4.4 1.6L12 15l-1.6-4.4L6 9l4.4-1.6L12 3Z"/><path d="m19 15 .8 2.2L22 18l-2.2.8L19 21l-.8-2.2L16 18l2.2-.8L19 15Z"/>', alert:'<path d="M12 3 2.5 20h19L12 3Z"/><path d="M12 9v5m0 3h.01"/>'
}
const icon=(name,size=18)=>`<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||''}</svg>`

let state={containers:clone(defaultContainers),cargo:clone(sampleCargo),settings:clone(defaultSettings),result:null,openResult:0,mobileNav:false,modal:null}
try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(saved?.containers&&saved?.cargo&&saved?.settings) state={...state,containers:saved.containers,cargo:saved.cargo,settings:saved.settings}}catch{}
const persist=()=>localStorage.setItem(STORAGE_KEY,JSON.stringify({containers:state.containers,cargo:state.cargo,settings:state.settings}))

function toast(message,kind='info'){
  let stack=$('.toast-stack');if(!stack){stack=document.createElement('div');stack.className='toast-stack';document.body.append(stack)}
  const el=document.createElement('div');el.className=`toast toast--${kind}`;el.innerHTML=`${icon(kind==='success'?'check':kind==='error'?'close':'info',17)}<span>${esc(message)}</span>`;stack.append(el);setTimeout(()=>el.remove(),3200)
}
function rotationLabel(mode){return mode==='free'?'자유 회전':mode==='upright'?'세움 유지':'방향 고정'}
function accessLabel(a){return a==='top'?'상부 개방':a==='side'?'측면 개방':'완전 개방'}
function unitCount(){return state.cargo.reduce((s,c)=>s+Math.max(0,Math.floor(c.quantity)),0)}
function totalOuterVolume(){return state.cargo.reduce((s,c)=>s+boxVolumeM3(c.length,c.width,c.height)*c.quantity,0)}
function totalWeight(){return state.cargo.reduce((s,c)=>s+c.weightKg*c.quantity,0)}

function containerCards(){return state.containers.map(c=>`<article class="container-card ${c.enabled?'is-selected':''}">
<button class="container-card__toggle" data-action="toggle-container" data-id="${esc(c.id)}" aria-pressed="${c.enabled}"><span class="select-dot">${c.enabled?icon('check',14):''}</span><div class="mini-container"><span class="mini-container__face"></span><span class="mini-container__side"></span></div><strong>${esc(c.name)}</strong><small>내측 ${fmt(c.length)} × ${fmt(c.width)} × ${fmt(c.height)} mm${c.doorWidth&&c.doorHeight?` · 문 ${fmt(c.doorWidth)} × ${fmt(c.doorHeight)}`:''}</small><div class="container-card__stats"><span><b>${c.nominalVolumeM3.toFixed(1)}</b> m³</span><span><b>${fmt(c.maxPayloadKg)}</b> kg</span></div></button>
<div class="container-card__actions"><button data-action="edit-container" data-id="${esc(c.id)}">${icon('edit',14)} 수정</button>${c.custom?`<button class="danger-link" data-action="delete-container" data-id="${esc(c.id)}">${icon('trash',14)} 삭제</button>`:''}</div></article>`).join('')}

function cargoRows(){return state.cargo.map(item=>`<tr><td><div class="cargo-name"><i style="background:${esc(item.color)}"></i><div><strong>${esc(item.name)}</strong><small>${item.canBeNested?'다른 화물 내부 삽입 가능':'외부 배치 전용'}</small></div></div></td>
<td><strong>${fmt(item.length)} × ${fmt(item.width)} × ${fmt(item.height)}</strong><small class="cell-sub">${boxVolumeM3(item.length,item.width,item.height).toFixed(3)} m³/개</small></td><td>${fmt(item.weightKg)} kg</td><td><strong>${fmt(item.quantity)}</strong>개</td>
<td><span class="status-chip">${rotationLabel(item.rotation)}</span><small class="cell-sub">${item.stackable?'상부 적재 허용':'상부 적재 금지'}</small></td>
<td>${item.innerSpace?.enabled?`<div class="inner-cell"><span class="status-chip status-chip--accent">${accessLabel(item.innerSpace.access)}</span><strong>${fmt(item.innerSpace.length)} × ${fmt(item.innerSpace.width)} × ${fmt(item.innerSpace.height)}</strong><small>${boxVolumeM3(item.innerSpace.length,item.innerSpace.width,item.innerSpace.height).toFixed(3)} m³/개</small></div>`:'<span class="muted">없음</span>'}</td>
<td class="align-right"><div class="row-actions"><button data-action="edit-cargo" data-id="${esc(item.id)}" aria-label="${esc(item.name)} 수정">${icon('edit',15)}</button><button class="danger" data-action="delete-cargo" data-id="${esc(item.id)}" aria-label="${esc(item.name)} 삭제">${icon('trash',15)}</button></div></td></tr>`).join('')}

function presetCards(){const rows=[['dense','최대 밀도','여유 0 mm · 공간 효율 우선','촘촘한 포장/개념 검토'],['practical','실무 권장','품목 10 mm · 벽 20 mm','일반 출하 계산의 기본값'],['safe','안전 여유','품목 30 mm · 벽 50 mm','취급 여유가 중요한 화물']];return rows.map(([id,title,desc,foot])=>`<button class="preset-card ${state.settings.preset===id?'is-selected':''}" data-action="preset" data-id="${id}"><span class="radio-dot"></span><strong>${title}</strong><span>${desc}</span><small>${foot}</small></button>`).join('')}

function shade(hex,amt){let c=String(hex).replace('#','');if(c.length===3)c=c.split('').map(x=>x+x).join('');const n=parseInt(c,16)||0;const r=Math.min(255,Math.max(0,(n>>16)+amt)),g=Math.min(255,Math.max(0,((n>>8)&255)+amt)),b=Math.min(255,Math.max(0,(n&255)+amt));return `rgb(${r},${g},${b})`}
function visualize(container){const spec=container.spec, scale=Math.min(.055,500/(spec.length+spec.width),180/spec.height),ox=255,oy=245;const proj=(x,y,z)=>({x:ox+(x-y)*scale*.78,y:oy+(x+y)*scale*.34-z*scale});const poly=a=>a.map(v=>`${v.x},${v.y}`).join(' ');const a=proj(0,0,0),b=proj(spec.length,0,0),c=proj(spec.length,spec.width,0),d=proj(0,spec.width,0),at=proj(0,0,spec.height),bt=proj(spec.length,0,spec.height),ct=proj(spec.length,spec.width,spec.height),dt=proj(0,spec.width,spec.height)
const boxes=[...container.placements].sort((p1,p2)=>(p1.x+p1.y+p1.z)-(p2.x+p2.y+p2.z)).map(p=>{const A=proj(p.x,p.y,p.z),B=proj(p.x+p.length,p.y,p.z),C=proj(p.x+p.length,p.y+p.width,p.z),D=proj(p.x,p.y+p.width,p.z),AT=proj(p.x,p.y,p.z+p.height),BT=proj(p.x+p.length,p.y,p.z+p.height),CT=proj(p.x+p.length,p.y+p.width,p.z+p.height),DT=proj(p.x,p.y+p.width,p.z+p.height);return `<g><polygon points="${poly([A,B,BT,AT])}" fill="${shade(p.color,-22)}" stroke="rgba(6,27,48,.36)" stroke-width=".8"/><polygon points="${poly([B,C,CT,BT])}" fill="${shade(p.color,-38)}" stroke="rgba(6,27,48,.36)" stroke-width=".8"/><polygon points="${poly([AT,BT,CT,DT])}" fill="${shade(p.color,18)}" stroke="rgba(6,27,48,.42)" stroke-width=".9"/></g>`}).join('')
const lines=[[a,b],[b,c],[c,d],[d,a],[at,bt],[bt,ct],[ct,dt],[dt,at],[a,at],[b,bt],[c,ct],[d,dt]].map(([p,q])=>`<line x1="${p.x}" y1="${p.y}" x2="${q.x}" y2="${q.y}" class="container-frame-line"/>`).join('')
const legend=[...new Map(container.placements.map(p=>[p.cargoId,p])).values()].map(p=>`<span><i style="background:${p.color}"></i>${esc(p.cargoName)}</span>`).join('')
return `<div class="visualizer-wrap"><svg viewBox="0 0 760 330" role="img" aria-label="${esc(spec.name)} 적재 배치 시각화" class="visualizer"><defs><linearGradient id="floor${container.index}" x1="0" x2="1"><stop offset="0%" stop-color="#edf4fa"/><stop offset="100%" stop-color="#dbe8f3"/></linearGradient></defs><polygon points="${poly([a,b,c,d])}" fill="url(#floor${container.index})" opacity=".8"/>${boxes}${lines}<text x="28" y="34" class="svg-title">${esc(spec.shortName)} · Container ${container.index}</text><text x="28" y="57" class="svg-subtitle">내측 ${fmt(spec.length)} × ${fmt(spec.width)} × ${fmt(spec.height)} mm</text></svg><div class="visualizer-legend">${legend}</div></div>`}
function groupPlacements(container){const m=new Map();container.placements.forEach(p=>{const g=m.get(p.cargoId)||{name:p.cargoName,count:0,weight:0,volume:0};g.count++;g.weight+=p.weightKg;g.volume+=boxVolumeM3(p.length,p.width,p.height);m.set(p.cargoId,g)});return [...m.values()]}
function resultsHtml(){const r=state.result;if(!r)return `<section class="panel pre-result"><div class="pre-result__icon">${icon('layers',24)}</div><div><strong>계산 전입니다.</strong><span>컨테이너 규격과 화물 조건을 확인한 뒤 최적화 계산을 실행하면 컨테이너 번호별 3D 배치, 좌표, 내부 공간 삽입 내역이 여기에 표시됩니다.</span></div></section>`
const totalNominal=r.containers.reduce((s,c)=>s+c.spec.nominalVolumeM3,0),totalUsed=r.containers.reduce((s,c)=>s+c.usedVolumeM3,0),totalPackedWeight=r.containers.reduce((s,c)=>s+c.usedWeightKg,0),nestedCount=r.nestedAssignments.reduce((s,a)=>s+a.placements.length,0)
const containerRows=r.containers.map((container,idx)=>{const open=state.openResult===idx, grouped=groupPlacements(container);const nested=container.nestedAssignments.length?`<div class="nested-list">${container.nestedAssignments.map(a=>{const gm=new Map();a.placements.forEach(p=>{const g=gm.get(p.cargoId)||{name:p.cargoName,count:0};g.count++;gm.set(p.cargoId,g)});return `<div class="nested-card"><div><strong>${esc(a.hostCargoName)}</strong><span>${esc(a.hostUid)}</span></div><b>${a.placements.length}개 삽입</b><small>${a.usedVolumeM3.toFixed(2)} / ${a.availableVolumeM3.toFixed(2)} m³ · ${fmt(a.usedWeightKg)} kg</small><ul>${[...gm.values()].map(x=>`<li>${esc(x.name)} × ${x.count}</li>`).join('')}</ul></div>`}).join('')}</div>`:'<div class="empty-mini">이 컨테이너에서는 화물 내부 빈 공간을 사용하지 않았습니다.</div>'
return `<article class="container-result"><button class="container-result__head" data-action="toggle-result" data-index="${idx}" aria-expanded="${open}"><div><strong>Container ${String(container.index).padStart(2,'0')} · ${esc(container.spec.name)}</strong><span>${container.placements.length}개 외부 배치 · ${container.nestedAssignments.reduce((s,a)=>s+a.placements.length,0)}개 내부 삽입</span></div><div class="head-meters"><span>용적 <b>${pct(container.volumeUtilization)}</b></span><span>중량 <b>${pct(container.weightUtilization)}</b></span>${icon(open?'up':'down',18)}</div></button>${open?`<div class="container-result__body">${visualize(container)}<div class="result-grid"><div class="result-table-wrap"><h3>외부 배치 화물</h3><table class="data-table compact"><thead><tr><th>화물</th><th>수량</th><th>점유 용적</th><th>중량</th></tr></thead><tbody>${grouped.map(g=>`<tr><td>${esc(g.name)}</td><td>${g.count}</td><td>${g.volume.toFixed(2)} m³</td><td>${fmt(g.weight)} kg</td></tr>`).join('')}</tbody></table></div><div class="result-table-wrap"><h3>내부 빈 공간 활용</h3>${nested}</div></div><details class="placement-details"><summary>정확한 좌표 및 방향 보기</summary><div class="coordinates-grid">${container.placements.map(p=>`<div><strong>${esc(p.cargoName)}</strong><span>${esc(p.uid)}</span><code>X ${Math.round(p.x)} · Y ${Math.round(p.y)} · Z ${Math.round(p.z)}</code><small>${Math.round(p.length)} × ${Math.round(p.width)} × ${Math.round(p.height)} mm · ${esc(p.orientation)}</small></div>`).join('')}</div></details></div>`:''}</article>`}).join('')
return `<section class="panel results-panel" id="results"><div class="section-head section-head--actions"><div><span class="section-number">4</span><div><h2>최적화 결과</h2><p>컨테이너별 적재 위치, 중량, 내측 공간 활용 결과를 확인하세요.</p></div></div><div class="button-row"><button class="button button--ghost" data-action="export-result-csv">${icon('download',16)} 배치 CSV</button><button class="button button--primary" data-action="export-result-json">${icon('save',16)} 전체 결과 JSON</button></div></div><div class="result-stats"><div class="metric">${icon('container',20)}<span>선정 컨테이너</span><strong>${r.containers.length}대</strong><small>${[...new Set(r.containers.map(c=>c.spec.shortName))].join(', ')||'-'}</small></div><div class="metric">${icon('calc',20)}<span>평균 공간 활용률</span><strong>${pct(totalNominal?totalUsed/totalNominal:0)}</strong><small>점유 외형 부피 기준</small></div><div class="metric">${icon('box',20)}<span>총 적재 중량</span><strong>${fmt(totalPackedWeight)} kg</strong><small>내부 삽입 화물 포함</small></div><div class="metric metric--accent">${icon('layers',20)}<span>내부 공간 활용</span><strong>${nestedCount}개</strong><small>${r.nestedSavedVolumeM3.toFixed(2)} m³ 외부 점유 절감</small></div></div>${r.unpacked.length?`<div class="warning-banner">${icon('alert',19)}<div><strong>${r.unpacked.length}개 화물을 적재하지 못했습니다.</strong><span>선택한 컨테이너의 내측 치수·중량 제한·회전/적층 조건을 확인하거나 사용자 규격을 추가하세요.</span></div></div>`:''}<div class="container-results">${containerRows||'<div class="empty-state">적재 가능한 컨테이너 결과가 없습니다.</div>'}</div><div class="calc-note">계산 시간 ${r.elapsedMs.toFixed(0)} ms · 직육면체 축정렬(orthogonal) 휴리스틱 기반입니다. 실제 출하 전에는 문 개구부, 고정/라싱, 무게중심, 바닥 하중, 제품 강성 등 현장 조건을 추가 확인하세요.</div></section>`}

function modalHtml(){if(!state.modal)return'';if(state.modal.type==='cargo'){const c=state.modal.item||{id:`cargo-${Date.now()}`,name:'',length:600,width:400,height:400,weightKg:10,quantity:1,rotation:'free',stackable:true,canBeNested:true,color:'#2f80ed',innerSpace:{enabled:false,length:0,width:0,height:0,access:'top'}};return `<div class="modal-backdrop"><form class="modal" data-form="cargo"><header class="modal__header"><div><h2>${state.modal.item?'화물 수정':'화물 추가'}</h2><p>기본 점유 공간은 외형 치수입니다. 비어 있는 내부 공간이 실제로 사용 가능하면 별도로 입력하세요.</p></div><button type="button" class="icon-button" data-action="close-modal" aria-label="닫기">${icon('close',20)}</button></header><div class="modal__body form-grid"><input type="hidden" name="id" value="${esc(c.id)}"><label class="field field--wide"><span>화물명</span><input required name="name" value="${esc(c.name)}" placeholder="예: 상부 개방 탱크"></label>${[['length','가로/길이 L (mm)',c.length],['width','세로/폭 W (mm)',c.width],['height','높이 H (mm)',c.height],['weightKg','단위 중량 (kg)',c.weightKg],['quantity','수량',c.quantity]].map(([n,l,v])=>`<label class="field"><span>${l}</span><input required type="number" min="${n==='weightKg'?0:1}" step="${n==='weightKg'?'0.1':'1'}" name="${n}" value="${v}"></label>`).join('')}<label class="field"><span>회전 조건</span><select name="rotation"><option value="free" ${c.rotation==='free'?'selected':''}>자유 회전 (6방향)</option><option value="upright" ${c.rotation==='upright'?'selected':''}>세워서 운송</option><option value="locked" ${c.rotation==='locked'?'selected':''}>방향 고정</option></select></label><div class="field field--wide field-row"><label class="check"><input type="checkbox" name="stackable" ${c.stackable?'checked':''}><span>위에 다른 화물을 적재할 수 있음</span></label><label class="check"><input type="checkbox" name="canBeNested" ${c.canBeNested?'checked':''}><span>다른 화물 내부 빈 공간에 넣을 수 있음</span></label><label class="color-field"><span>구분색</span><input type="color" name="color" value="${esc(c.color)}"></label></div><div class="inner-space field--wide"><div class="inner-space__head"><div><strong>내부 사용가능 공간</strong><p>탱크·프레임·빈 케이스처럼 외형 내부에 실제 적재 가능한 공간이 있을 때 입력합니다.</p></div><label class="switch"><input type="checkbox" name="innerEnabled" ${c.innerSpace?.enabled?'checked':''}><span></span></label></div><div class="inner-space__grid"><label class="field"><span>내측 L (mm)</span><input type="number" min="0" name="innerLength" value="${c.innerSpace?.length||0}"></label><label class="field"><span>내측 W (mm)</span><input type="number" min="0" name="innerWidth" value="${c.innerSpace?.width||0}"></label><label class="field"><span>내측 H (mm)</span><input type="number" min="0" name="innerHeight" value="${c.innerSpace?.height||0}"></label><label class="field"><span>접근 방향</span><select name="innerAccess"><option value="top" ${c.innerSpace?.access==='top'?'selected':''}>상부 개방</option><option value="side" ${c.innerSpace?.access==='side'?'selected':''}>측면 개방</option><option value="full" ${c.innerSpace?.access==='full'?'selected':''}>완전 개방</option></select></label><label class="field"><span>내부 허용 중량 (kg, 선택)</span><input type="number" min="0" name="innerMaxPayload" value="${c.innerSpace?.maxPayloadKg??''}"></label></div></div></div><footer class="modal__footer"><button type="button" class="button button--ghost" data-action="close-modal">취소</button><button class="button button--primary" type="submit">저장</button></footer></form></div>`}
const c=state.modal.item||{id:`custom-${Date.now()}`,name:'사용자 컨테이너',shortName:'CUSTOM',length:6000,width:2400,height:2400,doorWidth:2300,doorHeight:2300,maxPayloadKg:25000,nominalVolumeM3:34.56,enabled:true,custom:true};return `<div class="modal-backdrop"><form class="modal modal--small" data-form="container"><header class="modal__header"><div><h2>컨테이너 규격</h2><p>실제 사용 가능한 내측 치수와 최대 적재중량을 입력하세요.</p></div><button type="button" class="icon-button" data-action="close-modal">${icon('close',20)}</button></header><div class="modal__body form-grid"><input type="hidden" name="id" value="${esc(c.id)}"><label class="field field--wide"><span>규격명</span><input required name="name" value="${esc(c.name)}"></label>${[['length','내측 길이 L (mm)',c.length],['width','내측 폭 W (mm)',c.width],['height','내측 높이 H (mm)',c.height],['doorWidth','문 개구 폭 (mm, 선택)',c.doorWidth??''],['doorHeight','문 개구 높이 (mm, 선택)',c.doorHeight??''],['maxPayloadKg','최대 적재중량 (kg)',c.maxPayloadKg]].map(([n,l,v])=>`<label class="field"><span>${l}</span><input ${n.startsWith('door')?'':'required'} type="number" min="${n.startsWith('door')?0:1}" name="${n}" value="${v}"></label>`).join('')}</div><footer class="modal__footer"><button type="button" class="button button--ghost" data-action="close-modal">취소</button><button class="button button--primary" type="submit">저장</button></footer></form></div>`}

function render(){const y=window.scrollY;const usable=state.containers.filter(c=>c.enabled).length;document.getElementById('app').innerHTML=`<div class="app-shell"><aside class="sidebar ${state.mobileNav?'is-open':''}"><div class="brand"><div class="brand-mark">${icon('container',25)}</div><div><strong>Container Fit</strong><span>적재 최적화 계산기</span></div><button class="sidebar-close" data-action="mobile-close">${icon('close',22)}</button></div><nav class="side-nav"><button data-scroll="workspace">${icon('calc')}<span>포장 시뮬레이션</span></button><button data-scroll="containers">${icon('container')}<span>컨테이너 규격</span></button><button data-scroll="cargo">${icon('box')}<span>화물 목록</span></button><button data-scroll="settings">${icon('settings')}<span>여유·적재 조건</span></button><button data-scroll="results" ${state.result?'':'disabled'}>${icon('layers')}<span>결과 배치</span></button></nav><div class="sidebar-guide">${icon('info',19)}<strong>계산 원칙</strong><ol><li>컨테이너 내측 치수 사용</li><li>화물 외형으로 기본 점유</li><li>허용 시 내부 빈 공간 재사용</li><li>회전·적층·여유 간격 반영</li></ol></div><div class="sidebar-actions"><button data-action="export-project">${icon('save',16)}프로젝트 저장</button><button data-action="open-project-file">${icon('upload',16)}불러오기</button></div></aside><div class="main-column"><header class="topbar"><button class="mobile-menu" data-action="mobile-open">${icon('menu',22)}</button><div><strong>컨테이너 포장 최적화</strong><span>내측 빈 공간까지 계산하는 브라우저 기반 시뮬레이터</span></div><div class="topbar-actions"><button class="button button--ghost" data-action="reset">${icon('reset',16)} 초기화</button><button class="button button--ghost" data-action="export-project">${icon('download',16)} 저장</button></div></header><main id="workspace" class="workspace"><section class="intro-panel"><div><h1>외형은 점유하고, 실제로 비어 있는 내부 공간은 다시 활용합니다.</h1><p>컨테이너 내측 규격을 기준으로 화물의 가로·세로·높이, 중량, 회전, 적층 가능 여부와 탱크·프레임 내부의 사용 가능 공간을 함께 계산해 컨테이너 종류·수량·배치를 제안합니다.</p></div><div class="intro-summary"><div><span>화물</span><strong>${unitCount()}개</strong></div><div><span>외형 체적</span><strong>${totalOuterVolume().toFixed(2)} m³</strong></div><div><span>총 중량</span><strong>${fmt(totalWeight())} kg</strong></div></div></section><div class="steps">${[['1','컨테이너 선택','실제 내측 규격'],['2','화물 입력','외형 + 내부 공간'],['3','적재 조건','여유·회전·적층'],['4','최적화 계산','컨테이너별 배치']].map(([n,t,d],i)=>`<div class="step"><span>${n}</span><div><strong>${t}</strong><small>${d}</small></div>${i<3?`<span class="step-arrow">${icon('chevron',18)}</span>`:''}</div>`).join('')}</div>
<section class="panel" id="containers"><div class="section-head section-head--actions"><div><span class="section-number">1</span><div><h2>컨테이너 내측 규격</h2><p>계산에 사용할 규격만 선택하세요. 사용자 규격도 추가할 수 있습니다.</p></div></div><button class="button button--soft" data-action="add-container">${icon('plus',16)} 규격 추가</button></div><div class="container-cards">${containerCards()}</div></section>
<section class="panel" id="cargo"><div class="section-head section-head--actions"><div><span class="section-number">2</span><div><h2>화물 및 포장 단위</h2><p>외형 치수는 컨테이너 점유 공간으로, 내부 사용가능 치수는 작은 화물을 넣는 보조 적재공간으로 계산됩니다.</p></div></div><div class="button-row"><button class="button button--ghost" data-action="csv-template">${icon('download',16)} CSV 양식</button><button class="button button--ghost" data-action="open-csv-file">${icon('upload',16)} CSV 불러오기</button><button class="button button--primary" data-action="add-cargo">${icon('plus',16)} 화물 추가</button></div></div><div class="table-scroll"><table class="data-table cargo-table"><thead><tr><th>화물</th><th>외형 L × W × H</th><th>단위중량</th><th>수량</th><th>회전/적층</th><th>내부 사용가능 공간</th><th class="align-right">관리</th></tr></thead><tbody>${cargoRows()}</tbody></table></div>${state.cargo.length?'':'<div class="empty-state"><strong>아직 화물이 없습니다.</strong><span>화물 추가 또는 CSV 불러오기를 사용하세요.</span></div>'}</section>
<section class="panel" id="settings"><div class="section-head"><span class="section-number">3</span><div><h2>포장 방식과 여유 공간</h2><p>실제 작업 여유를 얼마만큼 둘지 선택하면 사용 가능한 내측 공간을 그만큼 줄여 계산합니다.</p></div></div><div class="preset-grid">${presetCards()}</div><div class="settings-grid"><label class="setting-control"><div><strong>화물 간 최소 간격</strong><span>좌우·앞뒤 배치 간격 (적층면은 직접 접촉)</span></div><div class="number-unit"><input data-setting="itemGap" type="number" min="0" max="200" value="${state.settings.itemGap}"><span>mm</span></div></label><label class="setting-control"><div><strong>컨테이너 벽면 여유</strong><span>좌우·앞뒤·천장 경계에서 제외</span></div><div class="number-unit"><input data-setting="wallClearance" type="number" min="0" max="300" value="${state.settings.wallClearance}"><span>mm</span></div></label><label class="setting-control"><div><strong>상부 적재 지지율</strong><span>아래 화물이 받쳐야 하는 바닥 면적</span></div><div class="number-unit"><input data-setting="supportRatioPct" type="number" min="50" max="100" value="${Math.round(state.settings.supportRatio*100)}"><span>%</span></div></label><label class="setting-toggle"><div><strong>화물 내부 빈 공간 활용</strong><span>상부 개방 탱크·빈 프레임 안에 작은 화물을 먼저 배치</span></div><label class="switch"><input data-setting="useInnerSpaces" type="checkbox" ${state.settings.useInnerSpaces?'checked':''}><span></span></label></label></div><div class="logic-note">${icon('spark',18)}<div><strong>내부 공간 활용 로직</strong><span>각 탱크/프레임의 내측 L×W×H를 별도 미니 컨테이너처럼 계산한 뒤, 들어갈 수 있는 작은 화물을 먼저 배치합니다. 내부로 들어간 화물은 외부 컨테이너 공간을 추가 점유하지 않지만 중량에는 포함됩니다.</span></div></div></section>
<section class="calculate-bar"><div><strong>현재 계산 대상</strong><span>${unitCount()}개 화물 · 외형 ${totalOuterVolume().toFixed(2)} m³ · ${usable}종 컨테이너 후보</span></div><button class="button button--calculate" data-action="calculate">${icon('calc',20)} 최적 컨테이너와 배치 계산</button></section>${resultsHtml()}<section class="method-panel">${icon('info',20)}<div><strong>계산 모델의 범위</strong><p>이 서비스는 직육면체 화물을 축 정렬 방식으로 배치하는 휴리스틱 계산기입니다. 내측 치수, 최대 적재중량, 품목 간격, 벽면 여유, 회전 조건, 상부 적재 가능 여부, 최소 지지면적, 화물 내부 사용가능 공간을 반영합니다. 기본 규격에 문 개구부가 있으면 배치 방향 기준 폭·높이 통과 여부도 확인합니다. 다만 실제 반입 회전 경로, 포크 진입 방향, 라싱, 제품별 압축강도, 바닥 점하중, 위험물 격리 등은 별도의 현장 검토가 필요합니다.</p></div></section></main><footer class="footer"><span>Container Fit · 브라우저에서 계산하고 LocalStorage에 자동 저장됩니다.</span><span>데이터는 별도 서버로 전송하지 않습니다.</span></footer></div>${modalHtml()}</div><input id="project-file" hidden type="file" accept="application/json,.json"><input id="csv-file" hidden type="file" accept=".csv,text/csv">`;requestAnimationFrame(()=>window.scrollTo(0,y))}

function downloadText(filename,text,type='application/json;charset=utf-8'){const b=new Blob([text],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=filename;a.click();URL.revokeObjectURL(u)}
const csvEscape=v=>/[",\n]/.test(String(v))?`"${String(v).replaceAll('"','""')}"`:String(v)
function exportProject(){downloadText('container-fit-project.json',JSON.stringify({version:1,containers:state.containers,cargo:state.cargo,settings:state.settings},null,2));toast('프로젝트 JSON을 저장했습니다.','success')}
function exportResultJson(){if(!state.result)return;downloadText('container-fit-result.json',JSON.stringify({generatedAt:new Date().toISOString(),settings:state.settings,containers:state.result.containers,unpacked:state.result.unpacked},null,2))}
function exportResultCsv(){if(!state.result)return;const rows=[['containerNo','containerType','cargo','unitId','x_mm','y_mm','z_mm','length_mm','width_mm','height_mm','weight_kg','orientation','nestedInside']];state.result.containers.forEach(c=>{c.placements.forEach(p=>rows.push([c.index,c.spec.name,p.cargoName,p.uid,p.x,p.y,p.z,p.length,p.width,p.height,p.weightKg,p.orientation,'']));c.nestedAssignments.forEach(a=>a.placements.forEach(p=>rows.push([c.index,c.spec.name,p.cargoName,p.uid,p.x,p.y,p.z,p.length,p.width,p.height,p.weightKg,p.orientation,a.hostUid]))) });downloadText('container-fit-placement.csv','\uFEFF'+rows.map(r=>r.map(csvEscape).join(',')).join('\n'),'text/csv;charset=utf-8')}
function csvTemplate(){downloadText('container-fit-cargo-template.csv','\uFEFFname,length,width,height,weightKg,quantity,rotation,stackable,canBeNested,color,innerLength,innerWidth,innerHeight,innerAccess,innerMaxPayload\n상부 개방 탱크,1800,1200,1200,180,2,upright,false,false,#0f8b8d,1500,900,820,top,700\n박스 A,600,400,350,12,18,free,true,true,#2f80ed,,,,,','text/csv;charset=utf-8')}
function parseSimpleCsv(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);const parseLine=line=>{const out=[];let cur='',q=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'){if(q&&line[i+1]==='"'){cur+='"';i++}else q=!q}else if(ch===','&&!q){out.push(cur);cur=''}else cur+=ch}out.push(cur);return out};const headers=parseLine(lines[0]).map(x=>x.trim());return lines.slice(1).map(line=>Object.fromEntries(headers.map((h,i)=>[h,(parseLine(line)[i]||'').trim()]))) }
async function importProject(file){try{const p=JSON.parse(await file.text());if(!Array.isArray(p.containers)||!Array.isArray(p.cargo)||!p.settings)throw 0;state.containers=p.containers;state.cargo=p.cargo;state.settings=p.settings;state.result=null;persist();render();toast('프로젝트를 불러왔습니다.','success')}catch{toast('올바른 Container Fit 프로젝트 JSON이 아닙니다.','error')}}
async function importCsv(file){try{const rows=parseSimpleCsv(await file.text());if(!rows.length)throw 0;const needed=['name','length','width','height','weightKg','quantity'];if(needed.some(k=>!(k in rows[0])))throw 0;const parsed=rows.map((r,i)=>({id:`csv-${Date.now()}-${i}`,name:r.name||`화물 ${i+1}`,length:Number(r.length),width:Number(r.width),height:Number(r.height),weightKg:Number(r.weightKg),quantity:Number(r.quantity),rotation:['free','upright','locked'].includes(r.rotation)?r.rotation:'free',stackable:r.stackable!=='false',canBeNested:r.canBeNested!=='false',color:r.color||['#2f80ed','#0f8b8d','#f2b84b','#7b61ff'][i%4],innerSpace:{enabled:Boolean(Number(r.innerLength)&&Number(r.innerWidth)&&Number(r.innerHeight)),length:Number(r.innerLength)||0,width:Number(r.innerWidth)||0,height:Number(r.innerHeight)||0,access:['top','side','full'].includes(r.innerAccess)?r.innerAccess:'top',maxPayloadKg:r.innerMaxPayload?Number(r.innerMaxPayload):undefined}}));if(parsed.some(x=>!x.name||x.length<=0||x.width<=0||x.height<=0||x.quantity<=0))throw 0;state.cargo=parsed;state.result=null;persist();render();toast(`${parsed.length}개 화물 유형을 불러왔습니다.`,'success')}catch{toast('CSV 형식을 확인하세요. 필수 헤더: name,length,width,height,weightKg,quantity','error')}}

function run(){const enabled=state.containers.filter(c=>c.enabled);if(!enabled.length)return toast('사용할 컨테이너 규격을 최소 1개 선택하세요.','error');if(!state.cargo.length||!unitCount())return toast('계산할 화물을 추가하세요.','error');if(unitCount()>500)return toast('브라우저 계산 안정성을 위해 한 번에 500개 이하로 계산해 주세요.','error');const invalid=state.cargo.find(c=>c.length<=0||c.width<=0||c.height<=0||c.quantity<=0||c.weightKg<0);if(invalid)return toast(`${invalid.name||'화물'}의 치수·수량·중량을 확인하세요.`,'error');state.result=optimizePacking(state.cargo,state.containers,state.settings);state.openResult=0;render();toast(state.result.unpacked.length?`계산 완료: ${state.result.unpacked.length}개는 현재 조건에서 적재되지 않았습니다.`:`계산 완료: ${state.result.containers.length}대에 전체 화물을 배치했습니다.`,state.result.unpacked.length?'info':'success');setTimeout(()=>$('#results')?.scrollIntoView({behavior:'smooth',block:'start'}),80)}

document.addEventListener('click',e=>{const btn=e.target.closest('[data-action],[data-scroll]');if(!btn)return;if(btn.dataset.scroll){state.mobileNav=false;render();setTimeout(()=>document.getElementById(btn.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'}),0);return}const action=btn.dataset.action,id=btn.dataset.id;if(action==='mobile-open'){state.mobileNav=true;render()}else if(action==='mobile-close'){state.mobileNav=false;render()}else if(action==='toggle-container'){state.containers=state.containers.map(c=>c.id===id?{...c,enabled:!c.enabled}:c);state.result=null;persist();render()}else if(action==='add-container'){state.modal={type:'container',item:null};render()}else if(action==='edit-container'){state.modal={type:'container',item:clone(state.containers.find(c=>c.id===id))};render()}else if(action==='delete-container'){state.containers=state.containers.filter(c=>c.id!==id);state.result=null;persist();render()}else if(action==='add-cargo'){state.modal={type:'cargo',item:null};render()}else if(action==='edit-cargo'){state.modal={type:'cargo',item:clone(state.cargo.find(c=>c.id===id))};render()}else if(action==='delete-cargo'){state.cargo=state.cargo.filter(c=>c.id!==id);state.result=null;persist();render()}else if(action==='close-modal'){state.modal=null;render()}else if(action==='preset'){state.settings={preset:id,...presetSettings[id]};state.result=null;persist();render()}else if(action==='calculate')run();else if(action==='reset'){if(confirm('입력한 화물·사용자 규격·설정을 예제 상태로 초기화할까요?')){state.containers=clone(defaultContainers);state.cargo=clone(sampleCargo);state.settings=clone(defaultSettings);state.result=null;persist();render();toast('예제 데이터로 초기화했습니다.','success')}}else if(action==='export-project')exportProject();else if(action==='open-project-file')$('#project-file').click();else if(action==='open-csv-file')$('#csv-file').click();else if(action==='csv-template')csvTemplate();else if(action==='toggle-result'){state.openResult=state.openResult===Number(btn.dataset.index)?-1:Number(btn.dataset.index);render()}else if(action==='export-result-json')exportResultJson();else if(action==='export-result-csv')exportResultCsv()})

document.addEventListener('change',e=>{const t=e.target;if(t.id==='project-file'&&t.files?.[0]){importProject(t.files[0]);t.value=''}else if(t.id==='csv-file'&&t.files?.[0]){importCsv(t.files[0]);t.value=''}else if(t.dataset.setting){const k=t.dataset.setting;if(k==='useInnerSpaces')state.settings={...state.settings,preset:'custom',useInnerSpaces:t.checked};else if(k==='supportRatioPct')state.settings={...state.settings,preset:'custom',supportRatio:Math.min(1,Math.max(.5,(Number(t.value)||50)/100))};else state.settings={...state.settings,preset:'custom',[k]:Math.max(0,Number(t.value)||0)};state.result=null;persist();render()}})

document.addEventListener('submit',e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const fd=new FormData(form);if(form.dataset.form==='cargo'){const item={id:fd.get('id'),name:String(fd.get('name')||'').trim(),length:Number(fd.get('length')),width:Number(fd.get('width')),height:Number(fd.get('height')),weightKg:Number(fd.get('weightKg')),quantity:Number(fd.get('quantity')),rotation:fd.get('rotation'),stackable:fd.has('stackable'),canBeNested:fd.has('canBeNested'),color:fd.get('color'),innerSpace:{enabled:fd.has('innerEnabled'),length:Number(fd.get('innerLength')||0),width:Number(fd.get('innerWidth')||0),height:Number(fd.get('innerHeight')||0),access:fd.get('innerAccess'),maxPayloadKg:fd.get('innerMaxPayload')?Number(fd.get('innerMaxPayload')):undefined}};if(!item.name||item.length<=0||item.width<=0||item.height<=0||item.quantity<=0)return toast('화물명과 외형 치수, 수량을 확인하세요.','error');const i=state.cargo.findIndex(x=>x.id===item.id);if(i>=0)state.cargo[i]=item;else state.cargo.push(item);state.modal=null;state.result=null;persist();render();toast('화물 정보가 저장되었습니다.','success')}else{const existing=state.containers.find(x=>x.id===fd.get('id'));const L=Number(fd.get('length')),W=Number(fd.get('width')),H=Number(fd.get('height'));const sameDims=existing&&L===existing.length&&W===existing.width&&H===existing.height;const item={id:fd.get('id'),name:String(fd.get('name')||'').trim(),shortName:existing?.shortName||'CUSTOM',length:L,width:W,height:H,doorWidth:fd.get('doorWidth')?Number(fd.get('doorWidth')):undefined,doorHeight:fd.get('doorHeight')?Number(fd.get('doorHeight')):undefined,maxPayloadKg:Number(fd.get('maxPayloadKg')),nominalVolumeM3:sameDims?existing.nominalVolumeM3:boxVolumeM3(L,W,H),enabled:existing?.enabled??true,custom:existing?existing.custom===true:true};if(!item.name||item.length<=0||item.width<=0||item.height<=0||item.maxPayloadKg<=0)return toast('컨테이너 내측 치수와 적재중량을 확인하세요.','error');const i=state.containers.findIndex(x=>x.id===item.id);if(i>=0)state.containers[i]={...state.containers[i],...item};else state.containers.push(item);state.modal=null;state.result=null;persist();render();toast('컨테이너 규격이 저장되었습니다.','success')}})

render()
